contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driving C.transfer
    function run(address[] calldata _tos, uint[] calldata v) public payable {
        // observe initial public getters
        address before_from = c.from();
        address before_caddress = c.caddress();

        // perform the call and record whether it reverted
        bool reverted = false;
        try c.transfer(_tos, v) returns (bool ok) {
            // call returned normally
            // we capture ok implicitly by not setting reverted
            // now assert properties below
        } catch {
            reverted = true;
        }

        // After the call (or revert) the public getters must remain equal to before
        // Also, if the call succeeded, it must have returned true. Since we cannot
        // read the returned value after try without capturing it, we assert that a
        // non-reverted call implies the function returned true by re-invoking
        // a view call pattern is not possible; instead we rely on semantics: try
        // returning means success. Thus assert: if not reverted then getters unchanged

        assert(c.from() == before_from && c.caddress() == before_caddress &&
               // if it reverted then at least one of the function's require conditions must have been possible
               // encode that: either msg.sender (which is this contract) was not equal to stored from,
               // or the _tos length was zero, or one of the v entries would violate the multiplication check.
               (
                   reverted ? (
                       // one of the three reasons holds
                       (address(this) != before_from) || (_tos.length == 0) || (_tos.length == v.length && _tos.length > 0 && _mulCheckFails(v))
                   ) : true
               )
        );
    }

    // helper view used inside the assert to check multiplication safety for all v entries
    // This is allowed because it's a local internal function and used in the assert; it does not call c.
    function _mulCheckFails(uint[] calldata arr) internal pure returns (bool) {
        // If any v[i] != 0 and (v[i]*1e18)/v[i] != 1e18 then the check fails.
        // For solidity math with unchecked overflow on multiplication in 0.8+, overflow causes revert at runtime,
        // but the original contract uses that pattern. We emulate the logical condition here without causing runtime revert by
        // performing the division first when possible: for non-zero v[i], ((v*i * 1e18) / v[i]) == 1e18 if no overflow occurred and exact.
        for (uint i = 0; i < arr.length; i++) {
            uint val = arr[i];
            if (val == 0) { continue; }
            // compute (val * 1e18) / val but avoid actual multiplication overflow: (val * 1e18) / val == 1e18 if val != 0
            // However if val*1e18 overflowed in original, the require would fail. We approximate overflow detection conservatively:
            // If val > type(uint).max / 1e18 then multiplication would overflow.
            uint max = type(uint).max / 1000000000000000000;
            if (val > max) {
                return true;
            }
            // otherwise the multiplication would not overflow and division gives 1e18
        }
        return false;
    }

    receive() external payable {}
}

