    function run(address[] memory _tos, uint[] memory v) public payable {
        // require lengths to match and non-empty to avoid the obvious reverts
        require(_tos.length == v.length && _tos.length > 0);
        // require each v[i] either zero or satisfies the multiplication/division identity
        for (uint i = 0; i < v.length; i++) {
            require(v[i] == 0 || ((v[i] * 1000000000000000000) / v[i]) == 1000000000000000000);
        }

        // observe public getters before the call
        address before_from = c.from();
        address before_caddress = c.caddress();

        // perform the call and record revert/success and return value if available
        bool reverted = false;
        bool returnedTrue = false;
        try c.transfer(_tos, v) returns (bool r) {
            returnedTrue = r;
        } catch {
            reverted = true;
        }

        // observe after-values
        address after_from = c.from();
        address after_caddress = c.caddress();

        // General rule: when inputs satisfy the transfer's internal numeric checks and lengths are valid,
        // either the call reverted (e.g. due to msg.sender not matching) or it returned true; in the latter case
        // the public stored addresses c.from() and c.caddress() must be unchanged.
        assert(reverted || (returnedTrue && after_from == before_from && after_caddress == before_caddress));
    }

    receive() external payable {}
