contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs: caller must simulate different tos and values; function is payable but we won't send Ether to c
    function run(address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length == v.length);
        // Record observable getters before the call
        address before_from = c.from();
        address before_caddress = c.caddress();

        bool reverted;
        bool ret;
        // call transfer and capture revert
        try c.transfer(_tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // After-call getters
        address after_from = c.from();
        address after_caddress = c.caddress();

        // Build the general rule as a single assert:
        // If call did not revert, then:
        //  - it returned true
        //  - public getters from and caddress did not change
        //  - preconditions enforced by contract must hold: msg.sender equals before_from and _tos.length>0 and for each i v[i]==0 or ((v[i]*1e18)/v[i])==1e18
        // Note: msg.sender for calls to c is this contract; so require that before_from equals address(this) when not reverted.
        bool preconds_ok = true;
        if (_tos.length == 0) preconds_ok = false;
        for (uint i = 0; i < v.length; i++) {
            if (!(v[i] == 0 || ((v[i] * 1000000000000000000) / v[i]) == 1000000000000000000)) {
                preconds_ok = false;
                break;
            }
        }

        // The assert encodes: not reverted => (ret==true && getters unchanged && before_from == address(this) && preconds_ok)
        assert(reverted || (ret == true && before_from == after_from && before_caddress == after_caddress && before_from == address(this) && preconds_ok));
    }

    // receive to allow this contract to hold Ether if needed
    receive() external payable {}
}

